using System.Security.Claims;using LocalPro.Web.Data;using LocalPro.Web.Domain;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages;[Authorize]public class NotificationsModel(AppDbContext db):PageModel{public List<Notification> Items{get;set;}=[];public async Task OnGetAsync(){var id=User.FindFirstValue(ClaimTypes.NameIdentifier)!;Items=await db.Notifications.AsNoTracking().Where(n=>n.UserId==id).OrderByDescending(n=>n.CreatedUtc).Take(100).ToListAsync();}public async Task<IActionResult> OnPostAsync(){var id=User.FindFirstValue(ClaimTypes.NameIdentifier)!;await db.Notifications.Where(n=>n.UserId==id&&!n.Read).ExecuteUpdateAsync(s=>s.SetProperty(n=>n.Read,true));return RedirectToPage();}}
